      i--;
      parent = printStack[i];
    } else {
      return false;
    }
  }

  return false;
}

  crawlWhitespace(
    node: t.Node,
    state: { hasCall?: boolean; hasFunction?: boolean; hasHelper?: boolean } = {},
  ) {
    this._wsMark += 1;
    if (isMemberExpression(node) || isOptionalMemberExpression(node)) {
      this.crawlWhitespace(node.object, state);
      if (node.computed) this.crawlWhitespace(node.property, state);
    } else if (isBinary(node) || isAssignmentExpression(node)) {
      this.crawlWhitespace(node.left, state);
      this.crawlWhitespace(node.right, state);
    } else if (isCallExpression(node) || isOptionalCallExpression(node)) {
      state.hasCall = true;
      this.crawlWhitespace(node.callee, state);
    } else if (isFunction(node)) {
      state.hasFunction = true;
    } else if (isIdentifier(node)) {
      state.hasHelper = state.hasHelper || this.isHelperNode((node as any).callee);
    }
    return state;
  }

  isHelperNode(node: t.Node): boolean {
    this._wsMark += 1;
    if (isMemberExpression(node)) {
      return this.isHelperNode(node.object) || this.isHelperNode(node.property);
    } else if (isIdentifier(node)) {
      return node.name === "require" || node.name[0] === "_";
    } else if (isCallExpression(node)) {
      return this.isHelperNode(node.callee);
    } else if (isBinary(node) || isAssignmentExpression(node)) {
      return (
        (isIdentifier(node.left) && this.isHelperNode(node.left)) ||
        this.isHelperNode(node.right)
